CREATE TABLE capacity_reservation_provisioning (reservation_id INTEGER NOT NULL PRIMARY KEY);
CREATE TABLE capacity_reservation_bound_storage_attachments (reservation_id INTEGER NOT NULL REFERENCES capacity_reservation_provisioning(reservation_id), role TEXT NOT NULL, observer TEXT NOT NULL, container_id TEXT, mount_target TEXT NOT NULL, source_target TEXT, read_only INTEGER NOT NULL, mount_id INTEGER NOT NULL, device_major INTEGER NOT NULL, device_minor INTEGER NOT NULL, statx_device_major INTEGER NOT NULL, statx_device_minor INTEGER NOT NULL, fs_type_magic INTEGER NOT NULL, filesystem_id_0 INTEGER, filesystem_id_1 INTEGER, filesystem_instance_digest TEXT NOT NULL, PRIMARY KEY (reservation_id, role, observer, mount_target));
CREATE TABLE capacity_reservation_provisioning_publications (reservation_id INTEGER NOT NULL REFERENCES capacity_reservation_provisioning(reservation_id), runner_id INTEGER NOT NULL, runner_name TEXT NOT NULL, runner_scale_set_id INTEGER NOT NULL, target TEXT NOT NULL, projection_sha256 TEXT NOT NULL, directory_device_major INTEGER NOT NULL, directory_device_minor INTEGER NOT NULL, directory_inode INTEGER NOT NULL, mount_id INTEGER NOT NULL, filesystem_id_0 INTEGER, filesystem_id_1 INTEGER, filesystem_instance_digest TEXT NOT NULL, read_only INTEGER NOT NULL, PRIMARY KEY (reservation_id, target));
CREATE INDEX capacity_bound_attachment_mount ON capacity_reservation_bound_storage_attachments (reservation_id, mount_id);
CREATE TRIGGER bound_attachment_no_update BEFORE UPDATE ON capacity_reservation_bound_storage_attachments BEGIN SELECT RAISE(ABORT, 'immutable storage attachment'); END;
CREATE TRIGGER bound_attachment_no_delete BEFORE DELETE ON capacity_reservation_bound_storage_attachments BEGIN SELECT RAISE(ABORT, 'immutable storage attachment'); END;
CREATE TRIGGER provisioning_publication_no_update BEFORE UPDATE ON capacity_reservation_provisioning_publications BEGIN SELECT RAISE(ABORT, 'immutable job-facts publication'); END;
CREATE TRIGGER provisioning_publication_no_delete BEFORE DELETE ON capacity_reservation_provisioning_publications BEGIN SELECT RAISE(ABORT, 'immutable job-facts publication'); END;
